SELECT *
FROM t
LATERAL VIEW POSEXPLODE(t.a) b
LATERAL VIEW POSEXPLODE(b.col.x) c;

SELECT *
FROM t
LATERAL VIEW POSEXPLODE(t.a) b
LATERAL VIEW POSEXPLODE(b.col.x) c AS pos, val;

SELECT *
FROM t
LATERAL VIEW EXPLODE(t.a) b AS lateral;

SELECT *
FROM t
LATERAL VIEW EXPLODE(t.a) b lateral
LATERAL VIEW EXPLODE(t.c) d;
